import {createServer as httpServer} from 'node:http';
import {createServer as netServer} from 'node:net';
import {spawn} from 'node:child_process';
import {mkdir,writeFile,mkdtemp,readFile,rm} from 'node:fs/promises';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {NativeToolBroker} from '../../../assets/scripts/native-tool-broker.mjs';
if (!process.env.ASB_CLAUDE_FIXTURE_DIR || !process.env.ASB_CLAUDE_BINARY) throw new Error('Set ASB_CLAUDE_FIXTURE_DIR and ASB_CLAUDE_BINARY');
const root=await mkdtemp(join(process.env.ASB_CLAUDE_FIXTURE_DIR,'edit-'));const workspace=join(root,'workspace');await mkdir(workspace);const file=join(workspace,'fixture.txt');
const binary=process.env.ASB_CLAUDE_BINARY;
const modulePath=fileURLToPath(new URL('../../../assets/scripts/claude-native-hook.mjs',import.meta.url));
const hook='node --input-type=module -e '+JSON.stringify(`import(${JSON.stringify(modulePath)}).then(m=>m.main()).catch(e=>{console.error(e.message);process.exitCode=1})`);
const settings={hooks:Object.fromEntries(['PreToolUse','PostToolUse','PostToolUseFailure'].map(n=>[n,[{matcher:'*',hooks:[{type:'command',command:hook,onFailure:'block',timeout:30}]}]]))};
let observed=[];const server=httpServer((req,res)=>{let body='';req.on('data',x=>body+=x);req.on('end',()=>{if(!body){res.writeHead(404);return res.end()}const d=JSON.parse(body);const results=[];for(const m of d.messages||[])if(Array.isArray(m.content))for(const x of m.content)if(x.type==='tool_result')results.push(x);observed=results;
const content=results.length===0?[{type:'tool_use',id:'toolu_read',name:'Read',input:{file_path:file}}]:results.length===1?[{type:'tool_use',id:'toolu_edit',name:'Edit',input:{file_path:file,old_string:'before',new_string:'after'}}]:[{type:'text',text:'done'}];res.writeHead(200,{'Content-Type':'application/json'});res.end(JSON.stringify({id:'msg_fixture',type:'message',role:'assistant',model:'claude-sonnet-4-5',content,stop_reason:results.length<2?'tool_use':'end_turn',stop_sequence:null,usage:{input_tokens:10,output_tokens:10}}))})});await new Promise(r=>server.listen(0,'127.0.0.1',r));
async function run(name,events){await writeFile(file,'before\n');const dir=join(root,name);await mkdir(dir);await mkdir(join(dir,'config'));await writeFile(join(dir,'settings.json'),JSON.stringify(settings));const socket=join(dir,'broker.sock'),marker=join(dir,'marker.sock');const markerServer=netServer(c=>{let data='';c.on('data',x=>{data+=x;if(data.includes('\n'))c.end('1\n')})});await new Promise(r=>markerServer.listen(marker,r));const effects=[];const broker=new NativeToolBroker(events?'replay':'record',events||[],async e=>{effects.push(e.ordinal)});await broker.listen(socket);
const env={...process.env,CLAUDE_CONFIG_DIR:join(dir,'config'),ANTHROPIC_BASE_URL:`http://127.0.0.1:${server.address().port}`,ANTHROPIC_AUTH_TOKEN:'fixture',ANTHROPIC_API_KEY:'',ANTHROPIC_DEFAULT_SONNET_MODEL:'claude-sonnet-4-5',ASB_CLAUDE_NATIVE_DIRECTORY:dir,ASB_CLAUDE_NATIVE_SOCKET:socket,ASB_CLAUDE_NATIVE_MARKER:marker,ASB_CLAUDE_NATIVE_MODE:events?'replay':'record'};
const child=spawn(binary,['-p','--no-session-persistence','--output-format','json','--model','sonnet','--dangerously-skip-permissions','--settings',join(dir,'settings.json'),'Use Read and Edit.'],{cwd:workspace,env,stdio:['ignore','pipe','pipe']});let out='',err='';child.stdout.on('data',x=>out+=x);child.stderr.on('data',x=>err+=x);const code=await new Promise(r=>child.on('exit',r));let recorded;try{recorded=await broker.finish()}finally{await new Promise(r=>markerServer.close(r))}return {code,output:JSON.parse(out),err,recorded,effects,file:await readFile(file,'utf8'),results:structuredClone(observed)};}
try{const record=await run('record');const replay=await run('replay',record.recorded);const ok=record.code===0&&replay.code===0&&record.file==='after\n'&&replay.file==='after\n'&&replay.effects.length===2&&JSON.stringify(record.results)===JSON.stringify(replay.results);console.log(JSON.stringify({ok,recordCode:record.code,replayCode:replay.code,tools:record.recorded.map(e=>e.request.tool),replayEffects:replay.effects,recordFile:record.file,replayFile:replay.file,recordSubtype:record.output.subtype,replaySubtype:replay.output.subtype,recordError:record.err,replayError:replay.err}));if(!ok)process.exitCode=1}finally{await new Promise(r=>server.close(r));await rm(root,{recursive:true,force:true})}
